import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-clsroom-observation',
  templateUrl: './clsroom-observation.page.html',
  styleUrls: ['./clsroom-observation.page.scss'],
})
export class ClsroomObservationPage implements OnInit {
  title:string;
  constructor(private router:Router,private route:ActivatedRoute) { }

  ngOnInit() {
    this.route.queryParams.subscribe(data => {
      console.log(data);
      this.title = data.title;

    })
  }

  goBack(){
    this.router.navigate(['/tabs/cwsn/dashboard'])
  }

}
